    return;
  }

  var n := arr.Length;
  var swapped: bool;
  var lastUnsorted := n - 1;

  ghost var originalMultiset := multiset(arr[..]);

  while (lastUnsorted > 0)
    invariant 0 <= lastUnsorted < n
    invariant forall i, j :: lastUnsorted < i < j < n ==> arr[i] <= arr[j]
    invariant forall i, j :: 0 <= i <= lastUnsorted < j < n ==> arr[i] <= arr[j]
    invariant multiset(arr[..]) == originalMultiset
    decreases lastUnsorted
  {
    swapped := false;
    var i := 0;

    while (i < lastUnsorted)
      invariant 0 <= i <= lastUnsorted
      invariant forall k :: 0 <= k < i ==> arr[k] <= arr[i]
      invariant forall k :: 0 <= k < i && k + 1 < n ==> arr[k] <= arr[k + 1]
      invariant multiset(arr[..]) == originalMultiset
      decreases lastUnsorted - i
    {
      if arr[i] > arr[i + 1] {
        // Swap elements
        var temp := arr[i];
        arr[i] := arr[i + 1];
        arr[i + 1] := temp;
        swapped := true;
      }
      i := i + 1;
    }

    // If no swaps occurred, array is sorted
    if !swapped {
      break;
    }

    // The last element is now in correct position
    lastUnsorted := lastUnsorted - 1;
  }

